  1→package checkpoint
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"log/slog"
  9→	"regexp"
 10→	"sort"
 11→	"strconv"
 12→	"strings"
 13→	"time"
 14→
 15→	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
 16→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 17→	"github.com/entireio/cli/cmd/entire/cli/logging"
 18→	"github.com/entireio/cli/cmd/entire/cli/paths"
 19→	"github.com/go-git/go-git/v6/plumbing"
 20→	"github.com/go-git/go-git/v6/plumbing/filemode"
 21→	"github.com/go-git/go-git/v6/plumbing/object"
 22→)
 23→
 24→// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
 25→// When a generation reaches this many checkpoints, it is archived
 26→// and a fresh /full/current is created.
 27→const DefaultMaxCheckpointsPerGeneration = 100
 28→
 29→// GenerationMetadata tracks the state of a /full/* generation.
 30→// A "generation" is a batch of raw transcripts stored under a single ref.
 31→// The active generation lives at /full/current; when it reaches the checkpoint
 32→// limit, it is archived as a numbered ref (e.g., /full/0000000000001) and a
 33→// fresh /full/current is created. Archived generations can later be cleaned up
 34→// based on their timestamps (see RFD-009 cleanup path).
 35→//
 36→// Stored at the tree root as generation.json and updated on every WriteCommitted.
 37→// UpdateCommitted (stop-time finalization) does NOT update this file since it
 38→// replaces an existing transcript rather than adding a new checkpoint.
 39→//
 40→// The generation's sequence number is derived from the ref name, not stored
 41→// in this struct. The checkpoint count is len(Checkpoints).
 42→type GenerationMetadata struct {
 43→	// Checkpoints is the list of checkpoint IDs stored in this generation.
 44→	// Used for finding which generation holds a specific checkpoint
 45→	// without walking the tree. len(Checkpoints) gives the count.
 46→	Checkpoints []id.CheckpointID `json:"checkpoints"`
 47→
 48→	// OldestCheckpointAt is the creation time of the earliest checkpoint.
 49→	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`
 50→
 51→	// NewestCheckpointAt is the creation time of the most recent checkpoint.
 52→	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
 53→}
 54→
 55→// readGeneration reads generation.json from the given tree hash.
 56→// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
 57→func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
 58→	if treeHash == plumbing.ZeroHash {
 59→		return GenerationMetadata{}, nil
 60→	}
 61→
 62→	tree, err := s.repo.TreeObject(treeHash)
 63→	if err != nil {
 64→		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
 65→	}
 66→
 67→	file, err := tree.File(paths.GenerationFileName)
 68→	if err != nil {
 69→		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
 70→			return GenerationMetadata{}, nil
 71→		}
 72→		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
 73→	}
 74→
 75→	content, err := file.Contents()
 76→	if err != nil {
 77→		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
 78→	}
 79→
 80→	var gen GenerationMetadata
 81→	if err := json.Unmarshal([]byte(content), &gen); err != nil {
 82→		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
 83→	}
 84→
 85→	return gen, nil
 86→}
 87→
 88→// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
 89→func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
 90→	_, treeHash, err := s.getRefState(refName)
 91→	if err != nil {
 92→		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
 93→	}
 94→	return s.readGeneration(treeHash)
 95→}
 96→
 97→// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
 98→// Returns a TreeEntry ready to be placed in a tree.
 99→func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
100→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
101→	if err != nil {
102→		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
103→	}
104→
105→	blobHash, err := CreateBlobFromContent(s.repo, data)
106→	if err != nil {
107→		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
108→	}
109→
110→	return object.TreeEntry{
111→		Name: paths.GenerationFileName,
112→		Mode: filemode.Regular,
113→		Hash: blobHash,
114→	}, nil
115→}
116→
117→// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
118→func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
119→	entry, err := s.marshalGenerationBlob(gen)
120→	if err != nil {
121→		return err
122→	}
123→	entries[paths.GenerationFileName] = entry
124→	return nil
125→}
126→
127→// updateGenerationForWrite reads the current generation metadata, appends the
128→// checkpoint ID (if not already present), and updates timestamps.
129→// Returns the updated metadata for the caller to write into the tree.
130→func (s *V2GitStore) updateGenerationForWrite(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, now time.Time) (GenerationMetadata, error) {
131→	gen, err := s.readGeneration(rootTreeHash)
132→	if err != nil {
133→		return GenerationMetadata{}, err
134→	}
135→
136→	// Only append if checkpoint ID is not already present (multi-session writes
137→	// to the same checkpoint should not duplicate the ID).
138→	found := false
139→	for _, existing := range gen.Checkpoints {
140→		if existing == checkpointID {
141→			found = true
142→			break
143→		}
144→	}
145→	if !found {
146→		gen.Checkpoints = append(gen.Checkpoints, checkpointID)
147→
148→		// Only update timestamps when a new checkpoint is added, so they reflect
149→		// checkpoint creation times rather than last-write times.
150→		if gen.OldestCheckpointAt.IsZero() {
151→			gen.OldestCheckpointAt = now
152→		}
153→		gen.NewestCheckpointAt = now
154→	}
155→
156→	return gen, nil
157→}
158→
159→// addGenerationToRootTree adds generation.json to an existing root tree, returning
160→// a new root tree hash. Preserves all existing entries (shard directories, etc.).
161→func (s *V2GitStore) addGenerationToRootTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
162→	entry, err := s.marshalGenerationBlob(gen)
163→	if err != nil {
164→		return plumbing.ZeroHash, err
165→	}
166→
167→	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
168→		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
169→}
170→
171→// generationRefWidth is the zero-padded width of archived generation ref names.
172→const generationRefWidth = 13
173→
174→// generationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
175→var generationRefPattern = regexp.MustCompile(`^\d{13}$`)
176→
177→// listArchivedGenerations returns the names of all archived generation refs
178→// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
179→func (s *V2GitStore) listArchivedGenerations() ([]string, error) {
180→	refs, err := s.repo.References()
181→	if err != nil {
182→		return nil, fmt.Errorf("failed to list references: %w", err)
183→	}
184→
185→	var archived []string
186→	err = refs.ForEach(func(ref *plumbing.Reference) error {
187→		name := ref.Name().String()
188→		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
189→			return nil
190→		}
191→		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
192→		if suffix == "current" || !generationRefPattern.MatchString(suffix) {
193→			return nil
194→		}
195→		archived = append(archived, suffix)
196→		return nil
197→	})
198→	if err != nil {
199→		return nil, fmt.Errorf("failed to iterate references: %w", err)
200→	}
201→
202→	sort.Strings(archived)
203→	return archived, nil
204→}
205→
206→// nextGenerationNumber returns the next sequential generation number for archiving.
207→// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
208→func (s *V2GitStore) nextGenerationNumber() (int, error) {
209→	archived, err := s.listArchivedGenerations()
210→	if err != nil {
211→		return 0, err
212→	}
213→
214→	var maxNum int64
215→	for _, name := range archived {
216→		n, parseErr := strconv.ParseInt(name, 10, 64)
217→		if parseErr != nil {
218→			continue // skip unparseable entries
219→		}
220→		if n > maxNum {
221→			maxNum = n
222→		}
223→	}
224→	return int(maxNum) + 1, nil
225→}
226→
227→// rotateGeneration archives the current /full/current generation and creates
228→// a fresh orphan. This is a 2-phase operation:
229→//
230→//  1. Archive: determine the next generation number, create a new ref pointing
231→//     to the current /full/current commit.
232→//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
233→//     point /full/current at it.
234→func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
235→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
236→
237→	// Guard against concurrent rotation: if another instance already rotated,
238→	// /full/current will have fewer checkpoints than the threshold.
239→	gen, err := s.readGenerationFromRef(refName)
240→	if err != nil {
241→		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
242→	}
243→	if len(gen.Checkpoints) < s.maxCheckpoints() {
244→		return nil
245→	}
246→
247→	currentRef, err := s.repo.Reference(refName, true)
248→	if err != nil {
249→		return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
250→	}
251→
252→	archiveNumber, err := s.nextGenerationNumber()
253→	if err != nil {
254→		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
255→	}
256→
257→	// Phase 1: Archive — create ref pointing to the current commit.
258→	// If the archive ref already exists, another instance already rotated — skip.
259→	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
260→	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
261→		logging.Info(ctx, "rotation: archive ref already exists, skipping",
262→			slog.String("archive_ref", string(archiveRefName)),
263→		)
264→		return nil
265→	}
266→	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
267→	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
268→		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
269→	}
270→
271→	// Verify /full/current hasn't been advanced by another writer since we read it.
272→	// If it changed, abort — the archive ref is harmless (points to a valid commit)
273→	// and the next writer will trigger rotation again.
274→	postArchiveRef, err := s.repo.Reference(refName, true)
275→	if err != nil {
276→		return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
277→	}
278→	if postArchiveRef.Hash() != currentRef.Hash() {
279→		logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
280→		return nil
281→	}
282→
283→	// Phase 2: Create fresh orphan /full/current
284→	seedGen := GenerationMetadata{
285→		Checkpoints: []id.CheckpointID{},
286→	}
287→	seedEntries := make(map[string]object.TreeEntry)
288→	if err := s.writeGeneration(seedGen, seedEntries); err != nil {
289→		return fmt.Errorf("rotation: failed to build seed generation: %w", err)
290→	}
291→	seedTreeHash, err := BuildTreeFromEntries(s.repo, seedEntries)
292→	if err != nil {
293→		return fmt.Errorf("rotation: failed to build seed tree: %w", err)
294→	}
295→
296→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
297→	orphanCommitHash, err := CreateCommit(s.repo, seedTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
298→	if err != nil {
299→		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
300→	}
301→
302→	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
303→	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
304→		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
305→	}
306→
307→	logging.Info(ctx, "generation rotation complete",
308→		slog.Int("archived_generation", archiveNumber),
309→		slog.String("archive_ref", string(archiveRefName)),
310→	)
311→
312→	return nil
313→}
314→

