// fetchRef runs `git fetch origin <refspec>` with a 2-minute timeout.
// When treeOnly is true, adds --depth=1 --filter=blob:none for treeless fetch.
func fetchRef(ctx context.Context, refSpec string, treeOnly bool) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	args := []string{"fetch"}
	if treeOnly {
		args = append(args, "--depth=1", "--filter=blob:none")
	}
	args = append(args, "origin", refSpec)

	fetchCmd := exec.CommandContext(ctx, "git", args...)
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return errors.New("fetch timed out after 2 minutes")
		}
		return fmt.Errorf("failed to fetch %s from origin: %s: %w", refSpec, strings.TrimSpace(string(output)), err)
	}

	return nil
}

