// resolveCheckpointReader returns the appropriate checkpoint reader and summary.
// Tries v2 first when enabled; falls back to v1. The returned reader should be
// used for all subsequent reads (session content) to avoid mixed v1/v2 reads.
func (s *ManualCommitStrategy) resolveCheckpointReader(ctx context.Context, checkpointID id.CheckpointID) (cpkg.CheckpointReader, *cpkg.CheckpointSummary, error) {
	// Try v2 first when enabled
	if settings.IsCheckpointsV2Enabled(ctx) {
		v2Store, v2Err := s.getV2CheckpointStore()
		if v2Err == nil {
			summary, readErr := v2Store.ReadCommitted(ctx, checkpointID)
			if readErr != nil {
				logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
					slog.String("checkpoint_id", string(checkpointID)),
					slog.String("error", readErr.Error()),
				)
			} else if summary != nil {
				return v2Store, summary, nil
			}
		}
	}

	// Fall back to v1
	store, err := s.getCheckpointStore()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	summary, err := store.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}

	return store, summary, nil
}

