// readSessionFunc reads the content of a specific session within a checkpoint.
type readSessionFunc func(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*cpkg.SessionContent, error)

// resolveCheckpointReader returns a session reader function and the checkpoint summary.
// Tries v2 first when enabled; falls back to v1. The returned function should be
// used for all subsequent reads to avoid mixed v1/v2 reads.
func (s *ManualCommitStrategy) resolveCheckpointReader(ctx context.Context, checkpointID id.CheckpointID) (readSessionFunc, *cpkg.CheckpointSummary, error) {
	// Try v2 first when enabled
	if settings.IsCheckpointsV2Enabled(ctx) {
		v2Store, v2Err := s.getV2CheckpointStore()
		if v2Err == nil {
			summary, readErr := v2Store.ReadCommitted(ctx, checkpointID)
			if readErr != nil {
				logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
					slog.String("checkpoint_id", string(checkpointID)),
					slog.String("error", readErr.Error()),
				)
			} else if summary != nil {
				return v2Store.ReadSessionContent, summary, nil
			}
		}
	}

	// Fall back to v1
	store, err := s.getCheckpointStore()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	summary, err := store.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}

	return store.ReadSessionContent, summary, nil
}

// RestoreLogsOnly restores session logs from a logs-only rewind point.
// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
// Does not modify the working directory.
// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
// If force is false, prompts for confirmation when local logs have newer timestamps.
// Returns info about each restored session so callers can print correct per-session resume commands.
func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
	if !point.IsLogsOnly {
		return nil, errors.New("not a logs-only rewind point")
	}

	if point.CheckpointID.IsEmpty() {
		return nil, errors.New("missing checkpoint ID")
	}

	// Resolve checkpoint reader: try v2 first when enabled, fall back to v1.
	// The chosen reader is used for both summary and session content reads —
	// no mixed reads between v1 and v2.
	reader, summary, err := s.resolveCheckpointReader(ctx, point.CheckpointID)
	if err != nil {
		return nil, err
	}
	if summary == nil {
		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
	}

